        return s.count('(')

    def count_close(s):
        return s.count(')')

    def is_good_concatenation(s1, s2):
        return count_open(s1) + count_open(s2) == count_close(s1) + count_close(s2) and \
               (count_open(s1) >= count_close(s1) and count_open(s2) >= count_close(s2))

    if is_good_concatenation(lst[0], lst[1]) or is_good_concatenation(lst[1], lst[0]):
        return 'Yes'
    else:
        return 'No'

